// ELEMENTS:
// 1. Fundo navy liso
// 2. Duas fotos (src, src2) em díptico reto com gutter fino — empilhadas em vertical, lado a lado em paisagem
// 3. As fotos entram em fade escalonado e derivam devagar em sentidos opostos
// 4. Rótulo opcional (label) por cima da legenda em serifa branca (anim.text)
// 5. Grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#001F44";
const INK = "#001F44";
const WHITE = "#FFFFFF";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.22) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.1, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

const SplitSlideDuo: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const H = box.height;
  const land = format === "landscape";
  const u = land ? H / 1080 : format === "half" ? (H / 960) * 0.85 : W / 1080;
  const T = Math.max(2, Math.round((anim.end - anim.start) * fps));
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const srcs = [String(p.src ?? ""), String(p.src2 ?? p.src ?? "")];
  const caption = String(anim.text ?? "").trim();
  const label = String(p.label ?? "").trim();

  const drift = interpolate(f, [0, T], [-2, 2], { ...clamp, easing: Easing.inOut(Easing.sin) });
  const show = (delay: number): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + 0.6) * fps)], [0, 1], { ...clamp, easing: EASE });
  const rise = (delay: number): React.CSSProperties => {
    const t = show(delay);
    return { opacity: t, transform: `translateY(${(1 - t) * 24 * u}px)` };
  };

  return (
    <AbsoluteFill style={{ textShadow: "0 2px 18px rgba(0,0,0,0.45)", backgroundColor: NAVY }}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          padding: land ? `${72 * u}px ${72 * u}px ${48 * u}px` : `${128 * u}px ${56 * u}px ${112 * u}px`,
          display: "flex",
          flexDirection: "column",
          gap: 20 * u,
          boxSizing: "border-box",
        }}
      >
        <div style={{ flex: 1, minHeight: 0, display: "flex", flexDirection: land ? "row" : "column", gap: 20 * u }}>
          {srcs.map((src, i) => (
            <div key={i} style={{ flex: 1, minHeight: 0, overflow: "hidden", opacity: show(i * 0.25) }}>
              {src ? (
                <Img
                  src={src}
                  style={{
                    width: "100%",
                    height: "100%",
                    objectFit: "cover",
                    filter: "saturate(0.88) contrast(1.05)",
                    transform: `scale(1.08) translate${land ? "Y" : "X"}(${(i === 0 ? drift : -drift)}%)`,
                  }}
                />
              ) : null}
            </div>
          ))}
        </div>
        {caption || label ? (
          <div style={{ display: "flex", flexDirection: "column", gap: 16 * u, paddingTop: 24 * u }}>
            {label ? (
              <div style={{ fontFamily: FONTS.body, fontWeight: 600, fontSize: 36 * u, letterSpacing: "0.22em", textTransform: "uppercase", color: WHITE, ...rise(0.6) }}>
                {label}
              </div>
            ) : null}
            <div style={{ fontFamily: FONTS.display, fontVariantNumeric: "lining-nums", fontWeight: 300, fontSize: 84 * u, lineHeight: 1.05, color: WHITE, ...rise(0.45) }}>{caption}</div>
          </div>
        ) : null}
      </div>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 6 * u, background: "#DE212B" }} />
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default SplitSlideDuo;
